<?php require dirname(__DIR__).'/includes/functions.php'; require_admin(); $title='Overview';
$stats=['Total products'=>one('SELECT COUNT(*) n FROM products WHERE active=1')['n'],'Total orders'=>one('SELECT COUNT(*) n FROM orders')['n'],'Customers'=>one('SELECT COUNT(*) n FROM users')['n'],'Realized COD sales'=>money(one("SELECT COALESCE(SUM(total),0) n FROM orders WHERE status='Delivered' AND payment_method='cod'")['n']),'Pending orders'=>one("SELECT COUNT(*) n FROM orders WHERE status='Pending'")['n'],'Low stock'=>one('SELECT COUNT(*) n FROM products WHERE active=1 AND stock<=5')['n']];
$months=[]; $counts=[]; $revenue=[]; $monthly=all("SELECT DATE_FORMAT(created_at,'%Y-%m') month,COUNT(*) orders,SUM(CASE WHEN status='Delivered' AND payment_method='cod' THEN total ELSE 0 END) revenue FROM orders WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 11 MONTH) AND status<>'Cancelled' GROUP BY month ORDER BY month");
$byMonth=array_column($monthly,null,'month'); for($i=11;$i>=0;$i--) { $key=date('Y-m',strtotime(date('Y-m-01')." -$i months")); $months[]=date('M y',strtotime($key.'-01')); $counts[]=(int)($byMonth[$key]['orders'] ?? 0); $revenue[]=(float)($byMonth[$key]['revenue'] ?? 0); }
$top=all("SELECT oi.product_name,SUM(oi.quantity) quantity FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.status<>'Cancelled' GROUP BY oi.product_id,oi.product_name ORDER BY quantity DESC LIMIT 5");
require __DIR__.'/_header.php'; ?>
<div class="stat-grid"><?php foreach($stats as $label=>$value): ?><article class="glass stat-card"><span><?= e($label) ?></span><strong><?= e($value) ?></strong><small>Store activity ↗</small></article><?php endforeach; ?></div><p class="small text-secondary mt-3">Sales count delivered cash-on-delivery orders. Unpaid demo payments are excluded from revenue.</p><div class="dashboard-charts"><section class="glass p-4"><h2>Monthly revenue</h2><div class="chart-box"><canvas id="revenue-chart" aria-label="Monthly revenue" role="img"></canvas></div></section><section class="glass p-4"><h2>Monthly orders</h2><div class="chart-box"><canvas id="orders-chart" aria-label="Monthly order counts" role="img"></canvas></div></section><section class="glass p-4"><h2>Top products</h2><div class="chart-box"><canvas id="products-chart" aria-label="Top products by units ordered" role="img"></canvas></div><?php if(!$top): ?><p>No orders yet.</p><?php endif; ?></section><section class="glass p-4"><h2>Stock watch</h2><?php foreach(all('SELECT id,name,stock FROM products WHERE active=1 AND stock<=5 ORDER BY stock LIMIT 10') as $p): ?><a class="summary-row" href="<?= url('admin/products.php?edit='.$p['id']) ?>"><span><?= e($p['name']) ?></span><strong><?= $p['stock'] ?> left ↗</strong></a><?php endforeach; ?></section></div><section class="glass p-4 mt-4"><h2>Recent orders</h2><div class="table-responsive"><table class="table"><thead><tr><th>Order</th><th>Customer</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach(all('SELECT * FROM orders ORDER BY id DESC LIMIT 8') as $o): ?><tr><td><a href="<?= url('admin/orders.php?id='.$o['id']) ?>"><?= e($o['order_number']) ?></a></td><td><?= e($o['full_name']) ?></td><td><?= e($o['status']) ?></td><td><?= money($o['total']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<script id="chart-data" type="application/json"><?= json_encode(['months'=>$months,'orders'=>$counts,'revenue'=>$revenue,'products'=>array_column($top,'product_name'),'quantities'=>array_column($top,'quantity')],JSON_HEX_TAG|JSON_HEX_AMP) ?></script><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.8/dist/chart.umd.min.js" defer></script><script src="<?= url('assets/js/admin.js') ?>" defer></script><?php require __DIR__.'/_footer.php'; ?>
